"""Opt-in live comparison on one visually reviewed public one-page PDF."""

import argparse
from concurrent.futures import ThreadPoolExecutor, as_completed
from decimal import Decimal
from hashlib import sha256
import json
import os
from pathlib import Path
import sys

ROOT = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(ROOT / 'backend'))
from reader import DocumentRead, checked_pdf, numeric_presence, run_cached, DEFAULT_MODEL

# Expected associations were independently read from the rendered official PDF,
# not generated by either tested provider. Only this exact content hash is scored.
SOURCE_URL = 'https://stats.mom.gov.sg/iMAS_Infographics/mrsd-Labour-market-outcomes-of-fresh-univ-grads.pdf'
REVIEWED_SHA256 = 'e1c1c63c080c49767f23dbc9dfe5dfb0d4c8b47c4a3ef286aa0c16c43a457d17'
EXPECTED = [
    ('employed_count', 2024, 6, 'people', '8600'), ('employed_count', 2025, 6, 'people', '9300'),
    ('unemployed_count', 2024, 6, 'people', '4300'), ('unemployed_count', 2025, 6, 'people', '6000'),
    ('outside_labour_force_count', 2024, 6, 'people', '5100'), ('outside_labour_force_count', 2025, 6, 'people', '2700'),
    ('permanent_employment_share', 2024, 6, 'percent', '36.9'), ('permanent_employment_share', 2025, 6, 'percent', '44.1'),
    ('employment_rate', 2025, 6, 'percent', '51.9'), ('employment_rate', 2025, 7, 'percent', '55.6'),
    ('unemployment_rate', 2025, 6, 'percent', '39.0'), ('unemployment_rate', 2025, 7, 'percent', '34.8'),
]


def score_associations(document):
    observations = [(s.metric_type, p.year, p.month, p.unit, Decimal(p.value))
                    for s in document.series for p in s.points]
    expected = [(*row[:4], Decimal(row[4])) for row in EXPECTED]
    actual = set(observations)
    return {'expected': len(expected), 'correct_associations': len(set(expected) & actual),
            'missing': [list(map(str, row)) for row in expected if row not in actual],
            'unexpected': [list(map(str, row)) for row in actual - set(expected)],
            'duplicate_observations': len(observations) - len(actual),
            'note': 'One visually reviewed PDF only. Not a general accuracy benchmark; population/cohort descriptions still require review.'}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--pdf', type=Path, required=True)
    parser.add_argument('--output-dir', type=Path, required=True)
    parser.add_argument('--live', action='store_true', help='Allow provider calls and usage charges on cache misses.')
    parser.add_argument('--refresh', action='store_true', help='Explicitly repeat paid calls despite a matching cache.')
    parser.add_argument('--model', default=DEFAULT_MODEL)
    args = parser.parse_args()
    if not args.live:
        parser.error('--live is required; this experiment calls external providers')
    from dotenv import load_dotenv
    load_dotenv(ROOT / '.env', override=False)
    content = checked_pdf(args.pdf)
    if sha256(content).hexdigest() != REVIEWED_SHA256:
        parser.error('This scoring fixture requires the reviewed MOM PDF; review a new document before adding expected values.')
    args.output_dir.mkdir(parents=True, exist_ok=True)
    results = {'pdf_sha256': REVIEWED_SHA256, 'source_url': SOURCE_URL, 'providers': {}}
    with ThreadPoolExecutor(max_workers=2) as pool:
        jobs = {pool.submit(run_cached, content, provider, args.output_dir / 'cache',
                            key=os.getenv('GEMINI_API_KEY'), model=args.model, refresh=args.refresh): provider
                for provider in ['gemini', 'vision']}
        for job in as_completed(jobs):
            provider = jobs[job]
            try:
                value, cached = job.result()
                results['providers'][provider] = {**value, 'cached': cached}
                print(json.dumps({'provider': provider, 'status': 'completed', 'cached': cached,
                                  'seconds': value['seconds']}), flush=True)
            except Exception as error:
                # Never emit full SDK exceptions, request headers or credential paths.
                results['providers'][provider] = {'error_type': type(error).__name__,
                    'status_code': getattr(getattr(error, 'response', None), 'status_code', None)}
                print(json.dumps({'provider': provider, **results['providers'][provider]}), flush=True)
    gemini = results['providers'].get('gemini', {}).get('result', {}).get('document')
    vision = results['providers'].get('vision', {}).get('result', {}).get('full_text_annotation')
    if gemini:
        document = DocumentRead.model_validate(gemini)
        results['association_check'] = score_associations(document)
        if vision:
            results['ocr_numeric_presence'] = numeric_presence(document, vision['text'])
    (args.output_dir / 'comparison.json').write_text(json.dumps(results, indent=2, ensure_ascii=False), encoding='utf-8')
    if vision:
        (args.output_dir / 'vision-text.txt').write_text(vision['text'], encoding='utf-8')
    print(json.dumps(results.get('association_check', {})), flush=True)
    return 1 if any('error_type' in r for r in results['providers'].values()) else 0


if __name__ == '__main__':
    raise SystemExit(main())
